{
  "plan_por_dia": [
    {
      "dia": 1,
      "frentes": ["a"],
      "por_que": "Definir alcance, implementar y hacer la primera tanda de tests en un bloque A/B/C con tope de requests. Es el frente más largo y conviene descubrir fallos temprano; mientras el pipeline corre, los otros frentes esperan."
    },
    {
      "dia": 2,
      "frentes": ["a"],
      "por_que": "Completar tests y corregir fallos de forma secuencial, con reintentos acotados y una reserva explícita de cuota para los otros frentes. Si se alcanza el tope asignado, se pausa el trabajo pesado hasta el reset."
    },
    {
      "dia": 3,
      "frentes": ["b"],
      "por_que": "Producir el caso de estudio con pocos requests: esquema, borrador de 4 páginas y una edición final. Se ejecuta con A/B/C detenido y sin abrir ciclos innecesarios de reescritura."
    },
    {
      "dia": 4,
      "frentes": ["c"],
      "por_que": "Preparar temas, preguntas y una simulación breve de entrevista, con consumo casi nulo. El día también sirve como buffer secuencial si (a) o (b) necesitan una corrección pendiente."
    },
    {
      "dia": 5,
      "frentes": ["a", "b", "c"],
      "por_que": "Con la cuota ya reseteada, hacer la corrida final de tests de (a) y cerrar cualquier ajuste de (b) y (c). Las tareas se encolan para revisión final; no se solapan con el pipeline A/B/C."
    }
  ],
  "advertencia_paralelismo": "No conviene lanzar (a), (b) y (c) juntas. Mientras A/B/C corre, ocupa los 3 slots y deja al CORE sin margen; agregar requests solo genera espera o 429 por cuenta, no por modelo, así que cambiar de modelo no lo resuelve. El paralelismo seguro es limitado: como máximo dos tareas livianas, por ejemplo (b)+(c), dejando un slot libre para el CORE; durante A/B/C no se lanza ningún otro frente.",
  "riesgo_de_cuota": "(a) es el frente que puede agotar el 61,3% restante antes del reset: implementación, generación de tests, diagnóstico y ciclos de corrección multiplican requests. Un bucle de fallos o reintentos sin tope puede consumir toda la semana. Hay que presupuestar sus bloques, limitar reintentos y reservar cuota para (b); (b) cuesta poco y (c) casi nada.",
  "orden_optimo": ["a", "b", "c"]
}
